import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the entire operation
custom_op_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void custom_op_kernel(const float* x, const float* bias, float* out, int size, int channels, int depth, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        int c = (idx / (depth * height * width)) % channels;
        float original_x = x[idx];
        float biased_x = original_x + bias[c];
        float res1 = biased_x + original_x;
        float res2 = res1 * original_x;
        out[idx] = res2 + original_x;
    }
}

torch::Tensor custom_op_cuda(torch::Tensor x, torch::Tensor bias) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    int channels = x.size(1);
    int depth = x.size(2);
    int height = x.size(3);
    int width = x.size(4);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    custom_op_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), bias.data_ptr<float>(), out.data_ptr<float>(), size, channels, depth, height, width);

    return out;
}
"""

custom_op_cpp_source = (
    "torch::Tensor custom_op_cuda(torch::Tensor x, torch::Tensor bias);"
)

# Compile the inline CUDA code for the custom operation
custom_op = load_inline(
    name="custom_op",
    cpp_sources=custom_op_cpp_source,
    cuda_sources=custom_op_source,
    functions=["custom_op_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.custom_op = custom_op

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.custom_op.custom_op_cuda(x, self.bias)
        return x
